sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var base = '';          // number prefix
    var ga = new GlideAggregate('x_gegis_ins_policy_case_task');

    if (!current.intake_case.nil()) {
        // Task directly on the intake case: number under the case number,
        // counting only case-level tasks (no parent).
        var caseRec = new GlideRecord('x_gegis_ins_policy_intake_case');
        if (!caseRec.get(current.intake_case + ''))
            return;
        base = caseRec.number + '';
        ga.addQuery('intake_case', current.intake_case + '');
        ga.addNullQuery('parent');

    } else if (!current.parent.nil()) {
        // Subtask under a parent task: number under the parent task's number,
        // counting that parent's existing children.
        var parentTask = current.parent.getRefRecord();
        if (!parentTask.isValidRecord())
            return;
        base = parentTask.number + '';
        ga.addQuery('parent', parentTask.getUniqueValue());

    } else {
        return;
    }

    ga.addAggregate('COUNT');
    ga.query();
    var count = 0;
    if (ga.next())
        count = parseInt(ga.getAggregate('COUNT'), 10) || 0;

    var seq = count + 1;
    var padded = seq < 10 ? '0' + seq : '' + seq;
    current.number = base + '-T' + padded;

})(current, previous);
